/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let itemId = event.payload.item.id;
    if (itemId)
        return {
            propName: 'listTable',
            value: itemId
        };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let itemId = event.payload.item.id;
    if (!itemId)
        return;
    if (event.payload.item.id === 'incident') {
        let openedFor = api.data.controller.form.fields.opened_for.value;
        let query = `caller_id=${openedFor}`;
        return {
            propName: "listQuery",
            value: query
        };
    } else
        return {
            propName: "listQuery",
            value: null
        };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		modalId: "list_viewport_modal",
		headerLabel: null,
		showModal: false,
		preserveState: null,
		displayOptions: null,
		bare: null,
		viewportElementId: null,
		viewportRoute: null,
		viewportFields: null,
		viewportParams: null
	};
}
